"""Everything that changes a player over time: match wear, weekly training,
injuries, reserves form, and the yearly cycle of growth, decline and retirement.

Growth model
------------
A player has a hidden ceiling (``potential``, OVR scale) and a hidden
``dev_rate``.  He closes the gap to that ceiling in two ways:

* weekly, during the season - faster if young, if the gap is big, if the club
  trains harder and if he is actually playing senior footy;
* one pre-season block each summer, with a big random swing, which is where
  breakouts (and the kid who never comes on) come from.

Gains are expressed in OVR points and then spread across the attributes that
matter for his position, tilted towards the club's training focus.
From 29 on the legs go first: speed and endurance fall away, footy IQ holds.
"""
from __future__ import annotations

import random

from . import constants as C
from .models import Game, Player
from .ratings import overall

WEEKLY_AGE_FACTOR = {18: 1.0, 19: 1.0, 20: 1.0, 21: .9, 22: .8, 23: .65, 24: .5, 25: .35, 26: .2, 27: .1}
SUMMER_SHARE = {19: .18, 20: .20, 21: .22, 22: .24, 23: .26, 24: .28, 25: .30, 26: .30, 27: .30}
BASE_INJURY = 0.026


def _clamp(x, lo, hi):
    return max(lo, min(hi, x))


def roll_injury(rng, minor: bool = False) -> dict:
    table = [i for i in C.INJURIES if not minor or i[2] <= 4]
    name, lo, hi, _ = rng.choices(table, weights=[i[3] for i in table])[0]
    return {"type": name, "weeks": rng.randint(lo, hi), "new": True}


def match_wear(game: Game, p: Player, tactics: dict, on_field: bool, rng) -> dict | None:
    """Fitness cost of a game and the chance of getting hurt in it."""
    tog = 1.0 if on_field else 0.6
    cost = (17.0 - 0.45 * p.attrs["endurance"]) * tog
    cost += {"low": -2.0, "medium": 0.0, "high": 3.5}[tactics["pressure"]]
    cost += {"slow": -1.0, "balanced": 0.0, "fast": 1.5}[tactics["tempo"]]
    if p.age >= 31:
        cost += 1.5
    risk = BASE_INJURY * tog * (0.5 + p.attrs["injury_prone"] / 10.0) * (1.0 + (100 - p.fitness) / 50.0)
    if p.age >= 31:
        risk *= 1.25
    p.fitness = _clamp(p.fitness - max(3.0, cost), 35.0, 100.0)
    if rng.random() < risk:
        p.injury = roll_injury(rng)
        return p.injury
    return None


def add_growth(p: Player, gain: float, focus_w: dict | None = None) -> None:
    """Raise OVR by ``gain`` points, spread over his position's attributes."""
    if gain <= 0:
        return
    w = C.POS_WEIGHTS[p.pos]
    focus_w = focus_w or {}
    norm = sum(wk * focus_w.get(k, 1.0) for k, wk in w.items())
    for k in w:
        p.attrs[k] = _clamp(p.attrs[k] + (gain / 5.0) * focus_w.get(k, 1.0) / norm, 1.0, 20.0)
    for k in C.SKILL_ATTRS:            # everything else creeps up a little too
        if k not in w and k != "ruck":
            p.attrs[k] = _clamp(p.attrs[k] + gain / 5.0 * 0.3 * focus_w.get(k, 1.0), 1.0, 20.0)


def weekly_tick(game: Game, rng, played: set | None = None) -> None:
    """One week of training, recovery and healing for every listed player."""
    played = played or set()
    for cid, club in game.clubs.items():
        focus = club.training.get("focus", "balanced")
        dev_mult, recover, risk_mult = C.TRAINING_INTENSITY[club.training.get("intensity", "normal")]
        focus_w = C.TRAINING_FOCUS[focus][1]
        if focus == "recovery":
            dev_mult, recover, risk_mult = 0.0, recover + 7.0, 0.3
        for p in game.squad(cid):
            if p.injury:
                if p.injury.pop("new", None):
                    pass                              # hurt this week: clock starts next week
                else:
                    p.injury["weeks"] -= 1
                    if p.injury["weeks"] <= 0:
                        p.injury = None
                        p.fitness = min(p.fitness, 88.0)   # short of a gallop on return
                        if cid == game.meta.get("user_club"):
                            game.add_news(f"{p.name} is fit again and available for selection.", "injury")
                p.fitness = _clamp(p.fitness + recover * 0.8, 35.0, 100.0)
                continue
            p.fitness = _clamp(p.fitness + recover, 35.0, 100.0)
            if p.id not in played:                    # a run in the twos
                p.reserves = round(_clamp(rng.gauss(5.6 + (overall(p) - 64.0) / 7.0, 1.1), 2.0, 10.0), 1)
                if rng.random() < 0.0035 * risk_mult * (0.5 + p.attrs["injury_prone"] / 10.0):
                    p.injury = roll_injury(rng, minor=True)
                    p.injury.pop("new")
                    if cid == game.meta.get("user_club"):
                        game.add_news(f"{p.name} hurt at training ({p.injury['type']}, "
                                      f"{p.injury['weeks']}w).", "injury")
            age_f = WEEKLY_AGE_FACTOR.get(p.age, 0.0)
            if age_f and dev_mult:
                gap = _clamp((p.potential - overall(p)) / 8.0, 0.0, 1.25)
                gain = 0.085 * p.dev_rate * club.dev * age_f * gap * dev_mult * rng.uniform(0.5, 1.5)
                if p.id in played:
                    gain *= 1.25                      # nothing develops a kid like senior footy
                add_growth(p, gain, focus_w)


# -- the yearly cycle ----------------------------------------------------------
def retirement_chance(p: Player) -> float:
    if p.age < 30:
        return 0.0
    o = overall(p)
    ch = 0.06 + 0.11 * (p.age - 30) + (0.25 if o < 68 else 0.0) - (0.10 if o >= 80 else 0.0)
    if p.injury and p.injury["weeks"] >= 20:
        ch += 0.25
    if p.age >= 36:
        ch = max(ch, 0.9)
    return _clamp(ch, 0.0, 0.97)


def process_retirements(game: Game, rng) -> list[Player]:
    gone = []
    for p in list(game.players.values()):
        if p.status == "listed" and rng.random() < retirement_chance(p):
            gone.append(p)
            games = p.career["games"]
            if overall(p) >= 78 or p.club == game.meta.get("user_club"):
                game.add_news(f"{p.name} ({p.club}, {p.age}) has announced his retirement"
                              + (f" after {games} games." if games else "."), "league")
            remove_player(game, p)
    return gone


def remove_player(game: Game, p: Player) -> None:
    """Take a player out of the game entirely (retired / never drafted)."""
    if p.club:
        club = game.clubs[p.club]
        club.lineup = {s: pid for s, pid in club.lineup.items() if pid != p.id}
        if club.captain == p.id:
            club.captain = None
    if p.id in game.free_agents:
        game.free_agents.remove(p.id)
    game.players.pop(p.id, None)


def new_year_progression(game: Game, rng) -> list[str]:
    """Birthday, pre-season growth and age-related decline.  Returns headlines
    about the user's players (breakouts and fades)."""
    notes = []
    user = game.meta.get("user_club")
    for p in game.players.values():
        if p.status == "prospect":
            continue
        before = overall(p)
        p.age += 1
        share = SUMMER_SHARE.get(p.age, 0.0)
        if share:
            swing = rng.choice([0.2, 0.6, 0.9, 1.0, 1.1, 1.4, 2.0])     # breakout or stall
            prog = game.clubs[p.club].dev if p.club else 1.0
            add_growth(p, min(max(0.0, p.potential - before),
                              max(0.0, p.potential - before) * share * p.dev_rate * prog * swing))
        if p.age >= 29:
            k = 1.0 if p.age <= 30 else 1.6 if p.age <= 32 else 2.3
            p.attrs["speed"] -= rng.uniform(0.1, 0.5) * k
            p.attrs["endurance"] -= rng.uniform(0.0, 0.4) * k
            for a in ("kicking", "marking", "handballing", "strength", "tackling", "goal_sense",
                      "intercept", "toughness", "ruck"):
                p.attrs[a] -= rng.uniform(0.0, 0.2) * k
            if p.age <= 31:
                p.attrs["decision"] += 0.15
        if p.age <= 30:
            p.attrs["leadership"] = _clamp(p.attrs["leadership"] + rng.uniform(0.2, 0.8), 1, 20)
            p.attrs["consistency"] = _clamp(p.attrs["consistency"] + rng.uniform(0.0, 0.4), 1, 20)
        for a in C.SKILL_ATTRS:
            p.attrs[a] = _clamp(p.attrs[a], 1.0, 20.0)
        after = overall(p)
        if p.age >= 28:
            p.potential = after
        else:
            p.potential = max(p.potential, after)
        # a summer off heals most things
        if p.injury:
            p.injury["weeks"] -= 22
            p.injury.pop("new", None)
            if p.injury["weeks"] <= 0:
                p.injury = None
        p.fitness, p.form, p.reserves = 100.0, [], 0.0
        # keep saves lean: only the last three seasons of stat lines
        for key in sorted(p.stats)[:-3]:
            del p.stats[key]
        if p.club == user and p.status == "listed":
            if after - before >= 3.5:
                notes.append(f"{p.name} ({p.age}) has had a huge pre-season: {before:.0f} -> {after:.0f}.")
            elif after - before <= -2.0:
                notes.append(f"{p.name} ({p.age}) is slowing down: {before:.0f} -> {after:.0f}.")
    return notes

files.models.py:
"""Core data models: Player, Club and the Game container.

Design notes
------------
* Everything is plain data (dataclasses + dicts/lists) so the whole career
  serialises to JSON with no custom encoders.  See storage.py.
* Players are stored once in ``Game.players`` keyed by id; clubs, lineups,
  draft pools and free-agent lists refer to them by id.
* Matches are plain dicts (see season.py) because their shape differs
  between "fixture", "played with summary" and "played with full detail".
"""
from __future__ import annotations

from dataclasses import dataclass, field, asdict, fields
from typing import Optional

from . import constants as C


@dataclass
class Player:
    id: int
    first: str
    last: str
    age: int
    height: int
    club: Optional[str]              # club id, or None (prospect / free agent)
    positions: list                  # position types, primary first e.g. ["CHB", "FB"]
    attrs: dict                      # attribute -> float 1..20 (shown rounded)
    potential: float                 # hidden ceiling on the 0-100 overall scale
    scout_noise: float = 0.0         # error in how non-owners perceive potential
    dev_rate: float = 1.0            # hidden: how fast he develops (0.6 - 1.4)
    wage: int = 0                    # $k per season
    contract_end: int = 0            # last season covered by the current deal
    rookie: bool = False             # on the rookie list
    status: str = "listed"           # listed | prospect | free_agent
    fitness: float = 100.0           # 100 = fresh
    form: list = field(default_factory=list)       # last five match ratings
    reserves: float = 0.0            # last reserves (twos) rating, 0 = n/a
    injury: Optional[dict] = None    # {"type": "hamstring", "weeks": 3}
    stats: dict = field(default_factory=dict)      # {"2027": {gm, k, hb, ...}}
    career: dict = field(default_factory=lambda: {"games": 0, "goals": 0})
    drafted: str = ""                # e.g. "2027 pick 4 (COL)"

    @property
    def name(self) -> str:
        return f"{self.first} {self.last}"

    @property
    def short(self) -> str:
        return f"{self.first[0]}. {self.last}"

    @property
    def pos(self) -> str:
        return self.positions[0]

    def season(self, year: int) -> dict:
        """Season stat line (created on demand)."""
        key = str(year)
        if key not in self.stats:
            self.stats[key] = {"gm": 0, "k": 0, "hb": 0, "m": 0, "t": 0, "g": 0,
                               "b": 0, "ho": 0, "cl": 0, "i50": 0, "rt": 0.0, "v": 0}
        return self.stats[key]

    def to_dict(self) -> dict:
        d = asdict(self)
        d["attrs"] = {k: round(v, 2) for k, v in self.attrs.items()}
        d["fitness"] = round(self.fitness, 1)
        d["potential"] = round(self.potential, 1)
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "Player":
        known = {f.name for f in fields(cls)}
        return cls(**{k: v for k, v in d.items() if k in known})


@dataclass
class Club:
    id: str
    name: str
    nickname: str
    ground: str
    state: str
    colours: str
    supporters: float                 # members, thousands
    balance: int = 0                  # $k in the bank
    dev: float = 1.0                  # development program quality (0.85 - 1.15)
    recruit: float = 1.0              # recruiting / scouting quality (0.85 - 1.15)
    strategy: str = "balanced"        # list strategy: contend | balanced | rebuild
    philosophy: str = "Balanced"      # coaching philosophy name (AI flavour)
    tactics: dict = field(default_factory=lambda: dict(C.DEFAULT_TACTICS))
    training: dict = field(default_factory=lambda: {"focus": "balanced", "intensity": "normal"})
    lineup: dict = field(default_factory=dict)     # slot -> player id
    captain: Optional[int] = None
    board: dict = field(default_factory=lambda: {"target": 12, "label": "", "confidence": 60.0})
    ledger: dict = field(default_factory=dict)     # season-to-date income/expense totals, $k
    last_ledger: dict = field(default_factory=dict)  # most recent round only

    @property
    def full_name(self) -> str:
        return self.name if self.nickname in self.name else f"{self.name} {self.nickname}"

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> "Club":
        known = {f.name for f in fields(cls)}
        d = {k: v for k, v in d.items() if k in known}
        # JSON turns nothing here into non-str keys, but lineup values must be ints
        d["lineup"] = {s: int(p) for s, p in d.get("lineup", {}).items()}
        return cls(**d)


class Game:
    """The whole career.  One instance == one save."""

    def __init__(self):
        self.meta: dict = {}          # year, phase, round, user club, cap ...
        self.clubs: dict[str, Club] = {}
        self.players: dict[int, Player] = {}
        self.season: dict = {}        # fixtures + results for the current year
        self.draft: dict = {}         # picks, prospect pool, live draft state
        self.free_agents: list = []   # player ids
        self.history: list = []       # one summary dict per completed season
        self.news: list = []          # newest last: {"year", "when", "text", "tag"}

    # -- convenience accessors ------------------------------------------------
    @property
    def year(self) -> int:
        return self.meta["year"]

    @property
    def phase(self) -> str:
        """preseason-less flow: season -> finals -> review -> contracts -> trades -> draft -> season"""
        return self.meta["phase"]

    @property
    def user(self) -> Optional[Club]:
        cid = self.meta.get("user_club")
        return self.clubs[cid] if cid else None

    @property
    def cap(self) -> int:
        return self.meta["cap"]

    def squad(self, club_id: str) -> list:
        return [p for p in self.players.values() if p.club == club_id and p.status == "listed"]

    def payroll(self, club_id: str) -> int:
        return sum(p.wage for p in self.squad(club_id))

    def new_player_id(self) -> int:
        self.meta["next_pid"] += 1
        return self.meta["next_pid"]

    def add_news(self, text: str, tag: str = "league", when: str = "") -> None:
        self.news.append({"year": self.year, "when": when or self.when(), "text": text, "tag": tag})
        if len(self.news) > 400:
            del self.news[:-400]

    def when(self) -> str:
        ph = self.phase
        if ph == "season":
            return f"R{self.meta['round']}"
        return {"finals": "Finals", "review": "Season review", "contracts": "Contracts",
                "trades": "Trade period", "draft": "Draft"}.get(ph, ph)

files.offseason.py:
"""List management and the off-season: contracts, delistings, free agency,
trades, the national draft and rolling the world into a new year.

Valuation
---------
Trades are judged with one common currency, "trade points":

* a player is worth roughly ``(effective_rating - 50) ^ 2.2 / 10`` where the
  effective rating blends in his (perceived) potential while he is young, and
  the total is discounted as he ages past 26;
* a draft pick is worth ``300 / (1 + 0.115 * (pick - 1)) ^ 1.25`` - pick 1 is
  a touch more than an established star, pick 18 about a good ordinary
  player, a fourth-rounder very little.  (A simplified take on the AFL's
  Draft Value Index; swapping in the real points table is a one-function job.)

AI clubs then bend those numbers by list strategy: rebuilders pay over the
odds for picks and kids, contenders for ready-made 24-30 year olds.
"""
from __future__ import annotations

import random

from . import constants as C
from . import development, finance, season
from .generator import market_wage, generate_draft_pool, add_draft_picks, pick_captain
from .models import Game, Player, Club
from .ratings import overall, auto_select, repair_lineup, best22_rating, shown_potential, scout_error

AI_LIST_TARGET = 42


# -- list bookkeeping ----------------------------------------------------------
def list_counts(game: Game, cid: str) -> tuple[int, int]:
    squad = game.squad(cid)
    rookies = sum(1 for p in squad if p.rookie)
    return len(squad) - rookies, rookies


def cap_space(game: Game, cid: str) -> int:
    return game.cap - game.payroll(cid)


def out_of_contract(game: Game, cid: str) -> list[Player]:
    return [p for p in game.squad(cid) if p.contract_end <= game.year]


def release_player(game: Game, p: Player) -> None:
    """Delist: he goes into the free-agent pool."""
    club = game.clubs.get(p.club)
    if club:
        club.lineup = {s: pid for s, pid in club.lineup.items() if pid != p.id}
        if club.captain == p.id:
            club.captain = None
    p.club, p.status, p.rookie = None, "free_agent", False
    if p.id not in game.free_agents:
        game.free_agents.append(p.id)


def sign_player(game: Game, p: Player, cid: str, wage: int, years: int, rookie: bool = False) -> None:
    if p.id in game.free_agents:
        game.free_agents.remove(p.id)
    if p.id in game.draft.get("pool", []):
        game.draft["pool"].remove(p.id)
    p.club, p.status, p.rookie = cid, "listed", rookie
    p.wage = C.ROOKIE_WAGE if rookie else int(wage)
    p.contract_end = game.year + years
    if cid == game.meta.get("user_club"):
        p.scout_noise = 0.0


# -- contracts -----------------------------------------------------------------
def contract_demand(game: Game, p: Player) -> dict:
    """What it takes to sign him: wage and acceptable contract lengths."""
    o = overall(p)
    wage = market_wage(o, p.age, p.potential, game.meta["wage_scale"])
    wage = int(round(wage * (1.0 + ((p.id * 7) % 9 - 4) * 0.012) / 5.0) * 5)   # some drive a harder bargain
    if p.age <= 23:
        lo, hi = 2, 4
    elif p.age <= 28:
        lo, hi = 2, 5
    elif p.age <= 30:
        lo, hi = 1, 3
    else:
        lo, hi = 1, 2
    if o < 66:
        lo, hi = 1, min(hi, 2)
    return {"wage": max(C.MIN_WAGE, wage), "min_years": lo, "max_years": hi}


def offer_contract(game: Game, p: Player, years: int, wage: int | None = None) -> tuple[bool, str]:
    """User offers a new deal to one of his own players or a free agent."""
    cid = game.meta["user_club"]
    d = contract_demand(game, p)
    own = p.club == cid
    if not own and p.status != "free_agent":
        return False, f"{p.name} is not available to sign."
    if own and p.contract_end > game.year + 1:
        return False, f"{p.name} is contracted to {p.contract_end} - no need to talk yet."
    if p.rookie and own and wage is None:
        # rookies simply roll over on the rookie list
        p.contract_end = game.year + 1
        return True, f"{p.name} stays on the rookie list for {game.year + 1} (${C.ROOKIE_WAGE}k)."
    wage = d["wage"] if wage is None else int(wage)
    if not d["min_years"] <= years <= d["max_years"]:
        return False, (f"{p.name} wants a {d['min_years']}-{d['max_years']} year deal, "
                       f"not {years} year{'s' if years != 1 else ''}.")
    ask = d["wage"] * (1.08 if not own else 1.0)
    if own and game.history and game.history[-1].get("user", {}).get("pos", 18) <= 4:
        ask *= 0.95                              # players take a little less to stay at a contender
    if wage < ask * 0.985:
        return False, f"{p.name} turns it down - he wants about ${int(round(ask / 5) * 5)}k a season."
    current = p.wage if own else 0
    if game.payroll(cid) - current + wage > game.cap:
        return False, (f"That deal would put you ${game.payroll(cid) - current + wage - game.cap}k over "
                       f"the ${game.cap}k salary cap.")
    if not own:
        senior, rookies = list_counts(game, cid)
        if senior + rookies >= C.LIST_MAX:
            return False, "Your list is full (44). Delist or trade someone first."
        rookie = senior >= C.SENIOR_MAX
        sign_player(game, p, cid, wage, years, rookie)
        game.add_news(f"{p.name} signs with {game.clubs[cid].name} as a free agent.", "list")
        return True, f"{p.name} signs for {years} year{'s' if years != 1 else ''} at ${p.wage}k."
    if p.rookie:
        senior, _ = list_counts(game, cid)
        if senior >= C.SENIOR_MAX:
            return False, "No room on the senior list (38) to upgrade him."
        p.rookie = False
    p.wage = wage
    p.contract_end = max(game.year, p.contract_end) + years
    return True, f"{p.name} re-signs to the end of {p.contract_end} at ${wage}k a season."


def delist(game: Game, p: Player) -> tuple[bool, str]:
    if game.phase in ("season", "finals"):
        return False, "Players can only be delisted in the off-season."
    if p.club != game.meta["user_club"]:
        return False, f"{p.name} is not on your list."
    payout = 0
    if p.contract_end > game.year:               # contracted players are paid out half of what's left
        payout = int(p.wage * (p.contract_end - game.year) * 0.5)
        finance._add(game.clubs[p.club], "contract_payouts", -payout)
    release_player(game, p)
    game.add_news(f"{game.user.name} delist {p.name}.", "list")
    return True, f"{p.name} has been delisted" + (f" (payout ${payout}k)." if payout else ".")


def _ai_contracts(game: Game, cid: str, rng) -> None:
    """Re-sign who is worth keeping, turn over the bottom of the list."""
    club = game.clubs[cid]
    squad = sorted(game.squad(cid), key=lambda p: player_value(game, p, perceived=False))
    ooc = [p for p in squad if p.contract_end <= game.year]
    cuts_needed = max(0, len(squad) - (AI_LIST_TARGET - 3)) + rng.choice([0, 0, 1, 1, 2])
    # Only the bottom of the list is ever at risk; out-of-contract players go first.
    fringe = sorted(squad[:cuts_needed + 5], key=lambda p: p.contract_end > game.year)
    cuts = {p.id for p in fringe[:cuts_needed]}
    for p in squad:
        if p.id in cuts:
            release_player(game, p)
    for p in ooc:
        if p.id in cuts:
            continue
        d = contract_demand(game, p)
        p.wage = C.ROOKIE_WAGE if p.rookie else d["wage"]
        p.contract_end = game.year + (1 if p.rookie else rng.randint(d["min_years"], d["max_years"]))
    # cap squeeze: shed the worst value-for-money contracts
    while game.payroll(cid) > game.cap * 0.985:
        squad = [p for p in game.squad(cid) if not p.rookie]
        if not squad:
            break
        worst = min(squad, key=lambda p: player_value(game, p, perceived=False) / max(1, p.wage))
        release_player(game, worst)
        if overall(worst) >= 76:
            game.add_news(f"Cap casualty: {club.name} part ways with {worst.name}.", "list")


# -- valuation -----------------------------------------------------------------
def player_value(game: Game, p: Player, perceived: bool = True) -> float:
    o = overall(p)
    pot = p.potential + (p.scout_noise if perceived else 0.0)
    youth = {18: .7, 19: .7, 20: .7, 21: .6, 22: .5, 23: .35, 24: .2}.get(p.age, 0.0)
    eff = o + max(0.0, pot - o) * youth
    v = max(0.0, eff - 50.0) ** 2.2 / 10.0
    if p.age > 26:
        v *= {27: .92, 28: .82, 29: .70, 30: .55, 31: .40, 32: .28}.get(p.age, .15)
    if p.injury and p.injury["weeks"] > 20:
        v *= 0.75
    return v


def pick_number(game: Game, pick: dict) -> float:
    """Best guess at where a pick will fall in the draft (1 = first)."""
    live = game.draft.get("live")
    if live and pick["year"] == game.draft.get("pool_year"):
        for o in live["order"]:
            if (o["round"], o["orig"]) == (pick["round"], pick["orig"]):
                return o["n"]
    if game.season.get("final_ladder") and pick["year"] == game.year:
        order = draft_order(game)
    elif pick["year"] == game.year and game.meta.get("round", 1) > 6 and game.phase == "season":
        order = [r["club"] for r in reversed(season.ladder(game))]
    else:
        order = sorted(game.clubs, key=lambda c: best22_rating(game, c))
    idx = order.index(pick["orig"])
    if pick["year"] > game.year:
        idx = 0.5 * idx + 0.5 * 8.5               # next year is anyone's guess
    return (pick["round"] - 1) * len(game.clubs) + idx + 1


def pick_value(game: Game, pick: dict) -> float:
    n = pick_number(game, pick)
    v = 300.0 / (1.0 + 0.115 * (n - 1)) ** 1.25
    return v * (0.85 if pick["year"] > game.year else 1.0)


def pick_label(pick: dict) -> str:
    lbl = f"{pick['year']} R{pick['round']}"
    return lbl + (f" ({pick['orig']})" if pick["orig"] != pick["owner"] else "")


def club_picks(game: Game, cid: str) -> list[dict]:
    return sorted((p for p in game.draft["picks"] if p["owner"] == cid),
                  key=lambda p: (p["year"], p["round"], p["orig"]))


def _ai_value(game: Game, club: Club, item, outgoing: bool) -> float:
    """How an AI club values a player or pick, given its list strategy."""
    if isinstance(item, dict):
        return pick_value(game, item) * {"rebuild": 1.15, "contend": 0.9}.get(club.strategy, 1.0)
    v = player_value(game, item)
    if club.strategy == "rebuild":
        v *= 1.15 if item.age <= 22 else 0.7 if item.age >= 28 else 1.0
    elif club.strategy == "contend":
        v *= 1.1 if 24 <= item.age <= 30 else 1.0
    if outgoing:
        squad = sorted(game.squad(club.id), key=overall, reverse=True)
        if item in squad[:3] and item.age < 29:
            v *= 1.35                             # franchise players cost extra
        elif item.age <= 21 and item.potential + item.scout_noise >= 84:
            v *= 1.2                              # so do the prized kids
    return v


def evaluate_trade(game: Game, ai_id: str, give: list, get: list) -> dict:
    """The user offers ``give`` to an AI club for ``get``.  Items are Player
    objects or pick dicts.  Returns the AI's verdict without changing anything."""
    user_id = game.meta["user_club"]
    ai = game.clubs[ai_id]
    for it in give:
        owner = it["owner"] if isinstance(it, dict) else it.club
        if owner != user_id:
            return {"ok": False, "msg": "You can only offer your own players and picks."}
    for it in get:
        owner = it["owner"] if isinstance(it, dict) else it.club
        if owner != ai_id:
            return {"ok": False, "msg": f"Everything you ask for must belong to {ai.name}."}
    if not give and not get:
        return {"ok": False, "msg": "Nothing to trade."}
    ai_in = sum(_ai_value(game, ai, it, False) for it in give)
    ai_out = sum(_ai_value(game, ai, it, True) for it in get)
    res = {"ai_in": round(ai_in), "ai_out": round(ai_out), "ok": False}
    gp = [x for x in give if isinstance(x, Player)]
    rp = [x for x in get if isinstance(x, Player)]
    for cid, incoming, outgoing in ((user_id, rp, gp), (ai_id, gp, rp)):
        name = game.clubs[cid].name
        if len(game.squad(cid)) + len(incoming) - len(outgoing) > C.LIST_MAX:
            res["msg"] = f"{name} would be over the list limit of {C.LIST_MAX}."
            return res
        pay = game.payroll(cid) + sum(p.wage for p in incoming) - sum(p.wage for p in outgoing)
        if pay > game.cap:
            res["msg"] = f"{name} can't fit the wages under the cap (would be ${pay - game.cap}k over)."
            return res
    if not get:
        res["msg"] = f"{ai.name} are happy to take a gift, but ask for something in return."
        return res
    need = ai_out * 1.08
    if ai_in >= need:
        res.update(ok=True, msg=f"{ai.name} accept. (They rate what they get at {ai_in:.0f} points "
                                f"and what they give up at {ai_out:.0f}.)")
    else:
        res["msg"] = (f"{ai.name} say no. They rate your offer at {ai_in:.0f} points and what you're "
                      f"asking for at {ai_out:.0f} - you need roughly {need - ai_in:.0f} more.")
    return res


def execute_trade(game: Game, a_id: str, b_id: str, a_gives: list, b_gives: list) -> None:
    for src, dst, items in ((a_id, b_id, a_gives), (b_id, a_id, b_gives)):
        for it in items:
            if isinstance(it, dict):
                it["owner"] = dst
            else:
                club = game.clubs[src]
                club.lineup = {s: pid for s, pid in club.lineup.items() if pid != it.id}
                if club.captain == it.id:
                    club.captain = None
                it.club = dst
                it.scout_noise = 0.0 if dst == game.meta.get("user_club") else it.scout_noise

    def desc(items):
        return ", ".join(pick_label(i) if isinstance(i, dict) else i.name for i in items) or "nothing"

    game.add_news(f"TRADE: {game.clubs[a_id].name} send {desc(a_gives)} to {game.clubs[b_id].name} "
                  f"for {desc(b_gives)}.", "trade")
    for cid in (a_id, b_id):
        if game.clubs[cid].captain is None:
            pick_captain(game, game.clubs[cid])


def _ai_trades(game: Game, rng) -> None:
    """Contenders shop picks to rebuilders for ready-made senior players."""
    user = game.meta.get("user_club")
    buyers = [c for c in game.clubs.values() if c.strategy != "rebuild" and c.id != user]
    sellers = [c for c in game.clubs.values() if c.strategy != "contend" and c.id != user]
    rng.shuffle(buyers)
    done = 0
    for buyer in buyers:
        if done >= 7:
            break
        picks = [p for p in club_picks(game, buyer.id) if p["year"] == game.year and p["round"] <= 3]
        if not picks:
            continue
        rng.shuffle(sellers)
        for seller in sellers[:6]:
            if seller.id == buyer.id:
                continue
            targets = [p for p in game.squad(seller.id) if 26 <= p.age <= 31 and overall(p) >= 75]
            rng.shuffle(targets)
            deal = None
            for t in targets[:4]:
                if game.payroll(buyer.id) + t.wage > game.cap or len(game.squad(buyer.id)) >= C.LIST_MAX:
                    continue
                for pk in picks:
                    gain_b = _ai_value(game, buyer, t, False) - _ai_value(game, buyer, pk, True)
                    gain_s = _ai_value(game, seller, pk, False) - _ai_value(game, seller, t, True)
                    if gain_b > 0 and gain_s > 0:
                        deal = (t, pk)
                        break
                if deal:
                    break
            if deal:
                execute_trade(game, buyer.id, seller.id, [deal[1]], [deal[0]])
                done += 1
                break


def _ai_free_agents(game: Game, rng) -> None:
    user = game.meta.get("user_club")
    clubs = [c for c in game.clubs.values() if c.id != user]
    rng.shuffle(clubs)
    for club in clubs:
        if len(game.squad(club.id)) >= AI_LIST_TARGET - 3:
            continue
        pool = sorted((game.players[pid] for pid in game.free_agents),
                      key=lambda p: player_value(game, p), reverse=True)
        for p in pool[:3]:
            d = contract_demand(game, p)
            if overall(p) >= 68 and game.payroll(club.id) + d["wage"] <= game.cap * 0.97:
                sign_player(game, p, club.id, d["wage"], d["min_years"])
                if overall(p) >= 74:
                    game.add_news(f"{club.name} snap up free agent {p.name}.", "list")
                break


# -- the draft -----------------------------------------------------------------
def draft_order(game: Game) -> list[str]:
    """Reverse finishing order: wooden-spooners first, premiers last."""
    lad = game.season.get("final_ladder") or [r["club"] for r in season.ladder(game)]
    finish = season.finals_finish(game)
    stage_rank = {"Elimination final": 0, "Semi final": 1, "Preliminary final": 2,
                  "Runner-up": 3, "Premier": 4}
    missed = [c for c in reversed(lad) if c not in finish]
    made = sorted((c for c in lad if c in finish),
                  key=lambda c: (stage_rank[finish[c]], -lad.index(c)))
    return missed + made


def prospect_score(game: Game, p: Player, viewer: str | None = None) -> float:
    """Consensus draft-board rating: mostly upside, some readiness.  AI clubs
    each see a slightly different player, so boards differ club to club."""
    pot = p.potential + p.scout_noise * scout_error(game, viewer)
    if viewer and viewer != game.meta.get("user_club"):
        pot += ((p.id * 31 + sum(map(ord, viewer))) % 9 - 4) * 0.8
    return 0.65 * min(99.0, pot) + 0.35 * overall(p)


def draft_board(game: Game) -> list[Player]:
    pool = [game.players[pid] for pid in game.draft["pool"] if pid in game.players]
    return sorted(pool, key=lambda p: prospect_score(game, p), reverse=True)


def open_draft(game: Game) -> None:
    order, n = [], 0
    base = draft_order(game)
    owners = {(p["round"], p["orig"]): p["owner"] for p in game.draft["picks"] if p["year"] == game.year}
    for rnd in range(1, C.DRAFT_ROUNDS + 1):
        for orig in base:
            n += 1
            order.append({"n": n, "round": rnd, "orig": orig, "owner": owners.get((rnd, orig), orig)})
    game.draft["live"] = {"order": order, "idx": 0, "log": []}


def _draft_select(game: Game, slot: dict, p: Player) -> None:
    cid = slot["owner"]
    senior, _ = list_counts(game, cid)
    rookie = senior >= C.SENIOR_MAX
    # draftees are on the standard scale: modest money, a little more for early picks
    base = {1: 190, 2: 160}.get(slot["round"], 140)
    wage = max(C.MIN_WAGE, int(round(base * game.cap / C.SALARY_CAP / 5) * 5))
    sign_player(game, p, cid, wage, 2, rookie)
    p.drafted = f"{game.year} pick {slot['n']} ({cid})"
    game.draft["live"]["log"].append([slot["n"], cid, p.id, p.name, p.pos, p.age])
    if slot["n"] <= 10 or cid == game.meta.get("user_club"):
        game.add_news(f"Draft pick {slot['n']}: {game.clubs[cid].name} select {p.name} ({p.pos}, {p.age}).", "draft")


def _ai_draft_choice(game: Game, cid: str) -> Player | None:
    board = [game.players[pid] for pid in game.draft["pool"]]
    if not board:
        return None
    club = game.clubs[cid]
    groups = {}
    for q in game.squad(cid):
        groups[C.POS_GROUP[q.pos]] = groups.get(C.POS_GROUP[q.pos], 0) + 1
    ideal = {"RK": 4, "KD": 5, "GD": 7, "WG": 4, "MD": 10, "GF": 7, "KF": 5}

    def score(p):
        s = prospect_score(game, p, cid)
        s += 0.8 * max(0, ideal[C.POS_GROUP[p.pos]] - groups.get(C.POS_GROUP[p.pos], 0))   # list need
        if club.strategy == "contend":
            s += 0.12 * (overall(p) - 55)          # contenders like the ready-made
        return s
    return max(board, key=score)


def draft_on_clock(game: Game) -> dict | None:
    live = game.draft.get("live")
    if not live or live["idx"] >= len(live["order"]):
        return None
    return live["order"][live["idx"]]


def run_draft(game: Game, stop_for_user: bool = True) -> list:
    """Make picks until it is the user's turn (or to the end).  Returns the new log lines."""
    live = game.draft["live"]
    user = game.meta.get("user_club")
    start = len(live["log"])
    while live["idx"] < len(live["order"]):
        slot = live["order"][live["idx"]]
        cid = slot["owner"]
        size = len(game.squad(cid))
        full = size >= C.LIST_MAX or not game.draft["pool"]
        if cid == user:
            if not full and stop_for_user:
                break
            if not full:                            # auto-pick for the user: best on the board
                board = draft_board(game)
                _draft_select(game, slot, board[0])
        elif not full and (size < AI_LIST_TARGET or slot["round"] == 1):
            p = _ai_draft_choice(game, cid)
            if p:
                _draft_select(game, slot, p)
        live["idx"] += 1
    return live["log"][start:]


def user_draft_pick(game: Game, p: Player) -> tuple[bool, str]:
    slot = draft_on_clock(game)
    if not slot or slot["owner"] != game.meta["user_club"]:
        return False, "You are not on the clock."
    if p.id not in game.draft["pool"]:
        return False, f"{p.name} is not in the draft pool."
    if len(game.squad(slot["owner"])) >= C.LIST_MAX:
        return False, "Your list is full - delist someone or pass."
    _draft_select(game, slot, p)
    game.draft["live"]["idx"] += 1
    return True, f"With pick {slot['n']}, {game.user.name} select {p.name}."


# -- phase transitions ---------------------------------------------------------
def season_review(game: Game, rng) -> dict:
    """Called once, straight after the Grand Final."""
    user = game.user
    review = finance.season_review(game)
    lad = game.season["final_ladder"]
    rows = {r["club"]: r for r in season.ladder(game)}
    finish = season.finals_finish(game)
    entry = {"year": game.year, "premier": game.season["premier"], "runner_up": game.season["runner_up"],
             "ladder": lad, "awards": game.season["awards"]}
    if user:
        r = rows[user.id]
        bnf = season.best_and_fairest(game, user.id, 3)
        entry["user"] = {"club": user.id, "pos": lad.index(user.id) + 1, "w": r["W"], "l": r["L"],
                         "d": r["D"], "finish": finish.get(user.id, ""),
                         "bnf": [[p.name, v] for v, p in bnf]}
        review["bnf"] = entry["user"]["bnf"]
    game.history.append(entry)
    retired = development.process_retirements(game, rng)
    review["retired"] = [[p.name, p.club, p.age, p.career["games"]] for p in retired
                         if user and p.club == user.id]
    review["retired_count"] = len(retired)
    if review.get("sacked"):
        game.meta["sacked"] = True
        game.add_news(f"The {user.name} board has sacked {game.meta.get('manager') or 'the coach'}.", "board")
    return review


def job_offers(game: Game) -> list[str]:
    """Clubs willing to hire a sacked coach: the bottom six that aren't his old one."""
    lad = game.season.get("final_ladder") or [r["club"] for r in season.ladder(game)]
    return [c for c in lad[-7:] if c != game.meta.get("user_club")][-6:]


def open_contracts(game: Game) -> None:
    """Start the off-season.  Next season's salary cap applies from here on, so
    every deal, trade and draft pick is measured against the cap it will count under."""
    game.meta["phase"] = "contracts"
    game.meta["cap"] = int(round(game.cap * C.CAP_GROWTH / 10.0) * 10)
    game.meta["wage_scale"] = round(game.meta["wage_scale"] * C.CAP_GROWTH, 3)
    game.add_news(f"The salary cap for {game.year + 1} is set at ${game.cap}k.", "league")


def close_contracts(game: Game, rng) -> list[str]:
    """Deadline day: unsigned players walk, AI clubs sort their lists out."""
    user = game.meta.get("user_club")
    lost = []
    for p in out_of_contract(game, user) if user else []:
        lost.append(p.name)
        release_player(game, p)
    if lost:
        game.add_news(f"Out of contract and gone from {game.user.name}: {', '.join(lost)}.", "list")
    for cid in game.clubs:
        if cid != user:
            _ai_contracts(game, cid, rng)
    # the oldest and weakest of the unwanted hang the boots up
    for pid in list(game.free_agents):
        p = game.players[pid]
        if p.age >= 31 or (p.age >= 27 and overall(p) < 64):
            development.remove_player(game, p)
    game.meta["phase"] = "trades"
    return lost


def close_trades(game: Game, rng) -> None:
    _ai_trades(game, rng)
    _ai_free_agents(game, rng)
    game.meta["phase"] = "draft"
    open_draft(game)
    run_draft(game, stop_for_user=True)


def finish_draft_and_roll_over(game: Game, rng) -> dict:
    """Complete the draft, top lists up, then tick the world over to next year."""
    run_draft(game, stop_for_user=False)
    user = game.meta.get("user_club")
    filled = []
    # undrafted kids and leftover free agents fill any list short of the minimum
    spare = sorted((game.players[pid] for pid in game.draft["pool"] + game.free_agents),
                   key=lambda p: prospect_score(game, p), reverse=True)
    for cid in game.clubs:
        while len(game.squad(cid)) < C.LIST_MIN and spare:
            p = spare.pop(0)
            senior, rookies = list_counts(game, cid)
            rookie = rookies < C.ROOKIE_MAX
            sign_player(game, p, cid, C.MIN_WAGE, 1, rookie)
            if cid == user:
                filled.append(p.name)
    # cap floor: clubs under 95% front-load their best players' deals
    for cid in game.clubs:
        short = int(game.cap * C.CAP_FLOOR_PCT) - game.payroll(cid)
        if short > 0:
            best = sorted((p for p in game.squad(cid) if not p.rookie), key=overall, reverse=True)[:8]
            for p in best:
                p.wage += int(round(short / len(best) / 5.0) * 5)
            if cid == user and short >= 50:
                game.add_news(f"To reach the salary floor, ${short}k was front-loaded into your "
                              f"leading players' contracts.", "list")
    draft_log = game.draft["live"]["log"]
    old_year = game.year
    new_cap = game.cap                              # already next season's (set when contracts opened)
    # Draftees and top-up signings can nudge a club over the cap.  Clubs fix that the
    # way real ones do: by restructuring senior deals.  (The user is stopped earlier
    # if he is over by more than this can cover - see commands.advance_step.)
    for cid in game.clubs:
        pay = game.payroll(cid)
        if pay > new_cap:
            k = new_cap * 0.998 / pay
            for p in game.squad(cid):
                if not p.rookie:
                    p.wage = max(C.MIN_WAGE, int(p.wage * k / 5.0) * 5)
            if cid == user:
                game.add_news(f"Contracts were restructured to fit your draftees under the cap "
                              f"(${pay - game.payroll(cid)}k trimmed from senior deals).", "list")
    for pid in list(game.draft["pool"]):            # the undrafted go back to state leagues
        development.remove_player(game, game.players[pid])
    keep = sorted((game.players[pid] for pid in game.free_agents),
                  key=lambda p: player_value(game, p), reverse=True)[:25]
    for pid in list(game.free_agents):
        if game.players[pid] not in keep:
            development.remove_player(game, game.players[pid])

    notes = development.new_year_progression(game, rng)
    game.meta["year"] = old_year + 1
    game.draft["picks"] = [p for p in game.draft["picks"] if p["year"] > old_year]
    add_draft_picks(game, game.year + 1)
    lad = game.season["final_ladder"]
    premier = game.season["premier"]
    ranking = sorted(game.clubs, key=lambda c: best22_rating(game, c), reverse=True)
    for cid, club in game.clubs.items():
        pos = lad.index(cid) + 1
        club.supporters = round(club.supporters * (1.0 + 0.04 * (9.5 - pos) / 8.5 + (0.03 if cid == premier else 0)), 1)
        i = ranking.index(cid)
        club.strategy = "contend" if i < 6 else "rebuild" if i >= 12 else "balanced"
        if club.captain not in {p.id for p in game.squad(cid)}:
            pick_captain(game, club)
    generate_draft_pool(game, rng)
    season.start_season(game, rng)
    finance.set_board_expectations(game)
    for cid, club in game.clubs.items():
        if cid == user and game.meta.get("selection") == "manual":
            repair_lineup(game, cid)
        else:
            club.lineup = auto_select(game, cid)
    game.add_news(f"The {game.year} season is here. Salary cap: ${game.cap}k.", "league", "Pre-season")
    return {"draft_log": draft_log, "filled": filled, "notes": notes, "year": game.year}

files.ratings.py:
"""Player ratings, team selection and list-strength helpers.

A player's rating in a role is a weighted average of the attributes that
matter there (constants.POS_WEIGHTS), scaled down if he is playing out of
position.  "Overall" (OVR, 0-100) is simply the 1-20 rating in his primary
position multiplied by five.
"""
from __future__ import annotations

from . import constants as C
from .models import Game, Player


# -- individual ratings ------------------------------------------------------
def raw_rating(attrs: dict, pos_type: str) -> float:
    """Weighted attribute average (1-20) for a position type."""
    return sum(attrs[a] * w for a, w in C.POS_WEIGHTS[pos_type].items())


def familiarity(player: Player, pos_type: str) -> float:
    """1.0 in his own position, sliding down the further out of position he is."""
    if pos_type == player.positions[0]:
        return 1.0
    if pos_type in player.positions:
        return 0.97
    mine = {C.POS_GROUP[p] for p in player.positions}
    grp = C.POS_GROUP[pos_type]
    if grp in mine:
        return 0.94
    if any(frozenset((grp, m)) in C.RELATED_GROUPS for m in mine):
        return 0.88
    return 0.78


def slot_rating(player: Player, pos_type: str) -> float:
    return raw_rating(player.attrs, pos_type) * familiarity(player, pos_type)


def overall(player: Player) -> float:
    """Current ability, 0-100."""
    return raw_rating(player.attrs, player.positions[0]) * 5.0


def ovr(player: Player) -> int:
    return int(round(overall(player)))


def shown_potential(game: Game, player: Player) -> int:
    """Potential as the user sees it: exact for his own list, fuzzy otherwise."""
    cur = overall(player)
    if player.club is not None and player.club == game.meta.get("user_club"):
        return int(round(max(cur, player.potential)))
    return int(round(max(cur, min(99, player.potential + player.scout_noise * scout_error(game)))))


def scout_error(game: Game, club_id: str | None = None) -> float:
    """How wrong a club's recruiters tend to be: 0.4 (elite) to 1.6 (poor)."""
    club = game.clubs.get(club_id or game.meta.get("user_club"))
    return 1.0 + (1.0 - club.recruit) * 4.0 if club else 1.0


def form_value(player: Player) -> float:
    """Average of the last five match ratings (6.0 = par)."""
    return sum(player.form) / len(player.form) if player.form else 6.0


def condition_mult(player: Player) -> float:
    """How fitness and form scale a player's output on match day."""
    fit = 0.86 + 0.14 * (player.fitness / 100.0)
    frm = 1.0 + (form_value(player) - 6.0) * 0.008
    return fit * frm


def available(player: Player) -> bool:
    return player.injury is None and player.status == "listed"


# -- selection ---------------------------------------------------------------
def auto_select(game: Game, club_id: str, youth_bias: float = 0.0) -> dict:
    """Pick the best available 23.

    Greedy assignment: rate every available player in every field slot, then
    repeatedly lock in the highest-rated (player, slot) pair still open.
    Players are naturally steered to their best role, and tired or out-of-form
    players slip behind fresher teammates.  ``youth_bias`` (rating points)
    is used by rebuilding AI clubs to get games into kids.
    """
    squad = [p for p in game.squad(club_id) if available(p)]
    pairs = []
    for p in squad:
        cm = condition_mult(p)
        bias = youth_bias * max(0, 23 - p.age) / 5.0 if youth_bias else 0.0
        for slot, pt in C.FIELD_SLOTS.items():
            pairs.append((slot_rating(p, pt) * cm + bias, slot, p.id))
    pairs.sort(reverse=True)
    lineup, used = {}, set()
    for _, slot, pid in pairs:
        if slot in lineup or pid in used:
            continue
        lineup[slot] = pid
        used.add(pid)
        if len(lineup) == len(C.FIELD_SLOTS):
            break
    # Interchange: best of the rest, favouring runners who can rotate anywhere.
    rest = []
    for p in squad:
        if p.id in used:
            continue
        util = 0.4 if C.POS_GROUP[p.pos] in ("MD", "WG", "GD", "GF") else 0.0
        bias = youth_bias * max(0, 23 - p.age) / 5.0 if youth_bias else 0.0
        rest.append((raw_rating(p.attrs, p.pos) * condition_mult(p) + util + bias, p.id))
    rest.sort(reverse=True)
    for slot, (_, pid) in zip(C.BENCH_SLOTS, rest):
        lineup[slot] = pid
    return lineup


def lineup_problems(game: Game, club_id: str) -> list[str]:
    """Human-readable reasons the current lineup can't take the field."""
    club = game.clubs[club_id]
    out, seen = [], set()
    for slot in C.ALL_SLOTS:
        pid = club.lineup.get(slot)
        p = game.players.get(pid) if pid is not None else None
        if p is None or p.club != club_id or p.status != "listed":
            out.append(f"{slot}: empty")
        elif p.injury:
            out.append(f"{slot}: {p.name} is injured ({p.injury['type']}, {p.injury['weeks']}w)")
        elif pid in seen:
            out.append(f"{slot}: {p.name} is named twice")
        seen.add(pid)
    return out


def repair_lineup(game: Game, club_id: str) -> list[str]:
    """Fill holes (injured / departed players) with the best available cover."""
    club = game.clubs[club_id]
    changes, used = [], set()
    for slot in C.ALL_SLOTS:               # keep every valid selection
        pid = club.lineup.get(slot)
        p = game.players.get(pid) if pid is not None else None
        if p and p.club == club_id and available(p) and pid not in used:
            used.add(pid)
        else:
            club.lineup.pop(slot, None)
    pool = [p for p in game.squad(club_id) if available(p) and p.id not in used]
    for slot in C.ALL_SLOTS:
        if slot in club.lineup or not pool:
            continue
        pt = C.FIELD_SLOTS.get(slot)
        key = (lambda p: slot_rating(p, pt) * condition_mult(p)) if pt else \
              (lambda p: raw_rating(p.attrs, p.pos) * condition_mult(p))
        best = max(pool, key=key)
        pool.remove(best)
        club.lineup[slot] = best.id
        changes.append(f"{best.name} comes in at {slot}")
    return changes


# -- list strength -----------------------------------------------------------
def best22_rating(game: Game, club_id: str) -> float:
    """Average OVR of the best 22 on the list, ignoring injuries (list quality)."""
    ovrs = sorted((overall(p) for p in game.squad(club_id)), reverse=True)[:22]
    return sum(ovrs) / max(1, len(ovrs))


def strength_ranking(game: Game) -> list[str]:
    """Club ids from strongest list to weakest."""
    return sorted(game.clubs, key=lambda c: best22_rating(game, c), reverse=True)


def line_ratings(game: Game, club_id: str) -> dict:
    """Average slot rating (0-100) of the selected defence, midfield and attack."""
    club = game.clubs[club_id]
    lines = {"D": [], "M": [], "F": []}
    for slot, pt in C.FIELD_SLOTS.items():
        p = game.players.get(club.lineup.get(slot))
        if p:
            lines[C.LINE_OF[pt]].append(slot_rating(p, pt) * 5)
    return {k: (sum(v) / len(v) if v else 0.0) for k, v in lines.items()}

files.season.py:
"""Season structure: fixture, ladder, playing rounds, finals and awards.

Phases of a year (``game.meta["phase"]``):

    season -> finals -> review -> contracts -> trades -> draft -> (next) season

``advance`` in offseason.py / commands.py walks through them; this module
owns everything up to the final siren of the Grand Final.
"""
from __future__ import annotations

import random

from . import constants as C
from . import development, finance
from .match_engine import simulate_match, score_str
from .models import Game
from .ratings import auto_select, repair_lineup, lineup_problems, overall

FINALS_WEEKS = ["Finals Week 1", "Semi Finals", "Preliminary Finals", "Grand Final"]


# -- fixture -------------------------------------------------------------------
def make_fixture(rng) -> list[list[list[str]]]:
    """23 rounds x 9 games.  Everyone meets once (17 rounds, circle method),
    then six return rounds; the nine traditional rivalries always meet twice."""
    n = len(C.CLUBS)
    arr = [None] * n
    pairs = C.RIVALRIES[:]
    rng.shuffle(pairs)
    for i, (a, b) in enumerate(pairs):       # seed the circle so round 0 = rivalry round
        if rng.random() < 0.5:
            a, b = b, a
        arr[i], arr[n - 1 - i] = a, b
    rounds, cur = [], arr[:]
    for r in range(n - 1):
        rd = []
        for i in range(n // 2):
            a, b = cur[i], cur[n - 1 - i]
            if (r + i) % 2:
                a, b = b, a
            rd.append([a, b])
        rounds.append(rd)
        cur = [cur[0], cur[-1]] + cur[1:-1]
    rivalry, others = rounds[0], rounds[1:]
    doubles = [rivalry] + rng.sample(others, 5)
    twice = {frozenset(m) for rd in doubles for m in rd}
    first = rounds[:]
    rng.shuffle(first)
    returns = [[[b, a] for a, b in rd] for rd in doubles]
    rng.shuffle(returns)
    fixture = first + returns
    # even out home games (11 or 12 each) by flipping one-off meetings
    home = {c[0]: 0 for c in C.CLUBS}
    for rd in fixture:
        for h, _ in rd:
            home[h] += 1
    for _ in range(40):
        flipped = False
        for rd in fixture:
            for m in rd:
                if frozenset(m) in twice:
                    continue
                if home[m[0]] - home[m[1]] >= 2:
                    home[m[0]] -= 1
                    home[m[1]] += 1
                    m[0], m[1] = m[1], m[0]
                    flipped = True
        if not flipped:
            break
    return fixture


def _new_match(game: Game, rnd, home: str, away: str, venue: str | None = None) -> dict:
    game.meta["next_mid"] += 1
    return {"id": game.meta["next_mid"], "rnd": rnd, "home": home, "away": away,
            "venue": venue or game.clubs[home].ground, "played": False}


def start_season(game: Game, rng=None) -> None:
    rng = rng or random
    fixture = make_fixture(rng)
    game.season = {
        "year": game.year,
        "rounds": [[_new_match(game, r + 1, h, a) for h, a in rd] for r, rd in enumerate(fixture)],
        "finals": [], "seeds": [], "awards": {}, "premier": None, "runner_up": None,
    }
    game.meta["phase"], game.meta["round"] = "season", 1
    for club in game.clubs.values():
        club.ledger, club.last_ledger = {}, {}


# -- ladder --------------------------------------------------------------------
def ladder(game: Game) -> list[dict]:
    rows = {cid: {"club": cid, "P": 0, "W": 0, "L": 0, "D": 0, "PF": 0, "PA": 0, "pts": 0}
            for cid in game.clubs}
    for rd in game.season["rounds"]:
        for m in rd:
            if not m["played"]:
                continue
            h, a, hp, ap = rows[m["home"]], rows[m["away"]], m["hs"][2], m["as"][2]
            h["P"] += 1; a["P"] += 1
            h["PF"] += hp; h["PA"] += ap; a["PF"] += ap; a["PA"] += hp
            if hp > ap:
                h["W"] += 1; a["L"] += 1; h["pts"] += 4
            elif ap > hp:
                a["W"] += 1; h["L"] += 1; a["pts"] += 4
            else:
                h["D"] += 1; a["D"] += 1; h["pts"] += 2; a["pts"] += 2
    out = list(rows.values())
    for r in out:
        r["pct"] = 100.0 * r["PF"] / r["PA"] if r["PA"] else 0.0
    out.sort(key=lambda r: (r["pts"], r["pct"], r["PF"]), reverse=True)
    for i, r in enumerate(out):
        r["pos"] = i + 1
    return out


def ladder_pos(game: Game, club_id: str) -> int:
    return next(r["pos"] for r in ladder(game) if r["club"] == club_id)


def club_matches(game: Game, club_id: str) -> list[dict]:
    ms = [m for rd in game.season["rounds"] for m in rd if club_id in (m["home"], m["away"])]
    ms += [m for wk in game.season["finals"] for m in wk["matches"] if club_id in (m["home"], m["away"])]
    return ms


def current_matches(game: Game) -> list[dict]:
    """The matches about to be played (this round / this week of finals)."""
    if game.phase == "season":
        return game.season["rounds"][game.meta["round"] - 1]
    if game.phase == "finals" and game.season["finals"]:
        return game.season["finals"][-1]["matches"]
    return []


def next_match(game: Game, club_id: str) -> dict | None:
    return next((m for m in current_matches(game)
                 if not m["played"] and club_id in (m["home"], m["away"])), None)


def find_match(game: Game, match_id: int) -> dict | None:
    for rd in game.season["rounds"]:
        for m in rd:
            if m["id"] == match_id:
                return m
    for wk in game.season["finals"]:
        for m in wk["matches"]:
            if m["id"] == match_id:
                return m
    return None


# -- playing matches -----------------------------------------------------------
def prepare_lineups(game: Game) -> list[str]:
    """AI clubs pick their sides.  The user's side is picked by the assistant
    coach when selection is 'auto'; in 'manual' it is only patched if invalid."""
    notes = []
    user = game.meta.get("user_club")
    for cid, club in game.clubs.items():
        if cid == user and game.meta.get("selection", "auto") == "manual":
            if lineup_problems(game, cid):
                notes = repair_lineup(game, cid)
        else:
            club.lineup = auto_select(game, cid, 0.25 if club.strategy == "rebuild" else 0.0)
    return notes


def _stat_line(st: dict) -> str:
    bits = [f"{st['k'] + st['hb']} disp"]
    if st["g"]:
        bits.append(f"{st['g']} goal{'s' if st['g'] > 1 else ''}")
    if st["m"] >= 6:
        bits.append(f"{st['m']} marks")
    if st["t"] >= 6:
        bits.append(f"{st['t']} tackles")
    if st["ho"] >= 15:
        bits.append(f"{st['ho']} hit-outs")
    if st["cl"] >= 6:
        bits.append(f"{st['cl']} clearances")
    return ", ".join(bits)


def play_match(game: Game, m: dict, rng, keep_detail: bool) -> dict:
    """Simulate one fixture and apply everything that flows from it."""
    final = not isinstance(m["rnd"], int)
    res = simulate_match(game, m["home"], m["away"], m["venue"], is_final=final, rng=rng)
    year = game.year
    m.update(played=True, hs=res["hs"], qs=res["qs"], wet=res["wet"], et=res["et"])
    m["as"] = res["as"]
    clubs = (game.clubs[m["home"]], game.clubs[m["away"]])

    # player consequences: stats, form, fitness, injuries
    injuries, gk = [], ([], [])
    for pid, st in res["players"].items():
        p = game.players[pid]
        s = p.season(year)
        s["gm"] += 1
        for k in ("k", "hb", "m", "t", "g", "b", "ho", "cl", "i50"):
            s[k] += st[k]
        s["rt"] = round(s["rt"] + st["rt"], 1)
        p.career["games"] += 1
        p.career["goals"] += st["g"]
        p.form = (p.form + [st["rt"]])[-5:]
        p.reserves = 0.0
        if st["g"]:
            gk[st["side"]].append((st["g"], p.short))
        inj = development.match_wear(game, p, clubs[st["side"]].tactics,
                                     st["slot"] in C.FIELD_SLOTS, rng)
        if inj:
            injuries.append({"pid": pid, "name": p.name, "club": p.club, **inj})
    if not final:
        for pid, v in zip(res["votes"], (3, 2, 1)):
            game.players[pid].season(year)["v"] += v
    m["best"] = [[game.players[pid].name, game.players[pid].club, res["players"][pid]["rt"],
                  _stat_line(res["players"][pid])] for pid in res["votes"]]
    m["gk"] = [", ".join(f"{n} {g}" if g > 1 else n for g, n in sorted(side, reverse=True)[:6])
               for side in gk]
    m["team"] = res["team"]
    m["inj"] = [[i["name"], i["club"], i["type"], i["weeks"]] for i in injuries]
    m["att"] = finance.match_day(game, m, rng)
    if keep_detail:
        m["detail"] = {"players": {str(pid): st for pid, st in res["players"].items()},
                       "comm": res["comm"], "tactics": res["tactics"],
                       "feed": res["feed"], "timeline": res["timeline"],
                       # names are kept so the report still reads after a player retires
                       "names": {str(pid): game.players[pid].short for pid in res["players"]}}
    finance.board_after_match(game, m)
    for i in injuries:
        if i["weeks"] >= 4 or i["club"] == game.meta.get("user_club"):
            game.add_news(f"{i['name']} ({i['club']}) - {i['type']}, out {i['weeks']} week"
                          f"{'s' if i['weeks'] != 1 else ''}.", "injury")
    return m


def play_round(game: Game, rng=None) -> dict:
    """Play the next home-and-away round for all 18 clubs."""
    rng = rng or random
    rnd = game.meta["round"]
    notes = prepare_lineups(game)
    user = game.meta.get("user_club")
    matches = game.season["rounds"][rnd - 1]
    for m in matches:
        play_match(game, m, rng, keep_detail=user in (m["home"], m["away"]) or game.meta.get("keep_all_detail", False))
    development.weekly_tick(game, rng, played=_who_played(matches, game))
    finance.weekly(game)
    report = {"kind": "round", "label": f"Round {rnd}", "matches": matches, "notes": notes,
              "user_match": next((m for m in matches if user in (m["home"], m["away"])), None)}
    if rnd >= C.HA_ROUNDS:
        _end_home_and_away(game)
        report["finals_set"] = True
    else:
        game.meta["round"] = rnd + 1
    return report


def _who_played(matches, game) -> set:
    played = set()
    for m in matches:
        for cid in (m["home"], m["away"]):
            played.update(game.clubs[cid].lineup.values())
    return played


# -- awards and finals ---------------------------------------------------------
def leaders(game: Game, key: str, n: int = 10, min_games: int = 1, club: str | None = None) -> list:
    """Season leaders.  key: g, disp, rt (average rating), v (votes), m, t, ho, cl."""
    y = str(game.year)
    rows = []
    for p in game.players.values():
        s = p.stats.get(y)
        if not s or s["gm"] < min_games or (club and p.club != club):
            continue
        if key == "disp":
            val = (s["k"] + s["hb"]) / s["gm"]
        elif key == "rt":
            val = s["rt"] / s["gm"]
        elif key in ("m", "t", "ho", "cl"):
            val = s[key] / s["gm"]
        else:
            val = s[key]
        rows.append((val, p))
    rows.sort(key=lambda r: r[0], reverse=True)
    return rows[:n]


def _end_home_and_away(game: Game) -> None:
    lad = ladder(game)
    s = game.season
    s["seeds"] = [r["club"] for r in lad[:8]]
    s["final_ladder"] = [r["club"] for r in lad]
    aw = s["awards"]
    v, p = leaders(game, "v", 1)[0]
    aw["brownlow"] = [p.name, p.club, int(v)]
    g, p = leaders(game, "g", 1)[0]
    aw["coleman"] = [p.name, p.club, int(g)]
    kids = [(val, pl) for val, pl in leaders(game, "rt", 400, min_games=10) if pl.age <= 21]
    if kids:
        aw["rising_star"] = [kids[0][1].name, kids[0][1].club, round(kids[0][0], 2)]
    game.add_news(f"Brownlow Medal: {aw['brownlow'][0]} ({aw['brownlow'][1]}) with {aw['brownlow'][2]} votes.", "award")
    game.add_news(f"Coleman Medal: {aw['coleman'][0]} ({aw['coleman'][1]}) with {aw['coleman'][2]} goals.", "award")
    game.add_news("Minor premiers: " + game.clubs[lad[0]['club']].full_name + ". The top eight is locked in.", "league")
    game.meta["phase"] = "finals"
    _schedule_finals_week(game)


def _schedule_finals_week(game: Game) -> None:
    s = game.season
    seeds = s["seeds"]
    rank = {c: i for i, c in enumerate(seeds)}

    def res(label):      # (winner, loser) of an earlier final
        for wk in s["finals"]:
            for m in wk["matches"]:
                if m["rnd"] == label:
                    return (m["home"], m["away"]) if m["hs"][2] > m["as"][2] else (m["away"], m["home"])

    def mk(label, a, b, venue=None):
        if rank[a] > rank[b]:
            a, b = b, a                       # higher seed hosts
        return _new_match(game, label, a, b, venue)

    week = len(s["finals"])
    if week == 0:
        ms = [mk("QF1", seeds[0], seeds[3]), mk("QF2", seeds[1], seeds[2]),
              mk("EF1", seeds[4], seeds[7]), mk("EF2", seeds[5], seeds[6])]
    elif week == 1:
        ms = [mk("SF1", res("QF1")[1], res("EF1")[0]), mk("SF2", res("QF2")[1], res("EF2")[0])]
    elif week == 2:
        ms = [mk("PF1", res("QF1")[0], res("SF2")[0]), mk("PF2", res("QF2")[0], res("SF1")[0])]
    else:
        ms = [mk("GF", res("PF1")[0], res("PF2")[0], C.GRAND_FINAL_VENUE)]
    s["finals"].append({"name": FINALS_WEEKS[week], "matches": ms})


def play_finals_week(game: Game, rng=None) -> dict:
    rng = rng or random
    notes = prepare_lineups(game)
    user = game.meta.get("user_club")
    wk = game.season["finals"][-1]
    for m in wk["matches"]:
        play_match(game, m, rng, keep_detail=True)   # every final keeps its full record
    development.weekly_tick(game, rng, played=_who_played(wk["matches"], game))
    report = {"kind": "finals", "label": wk["name"], "matches": wk["matches"], "notes": notes,
              "user_match": next((m for m in wk["matches"] if user in (m["home"], m["away"])), None)}
    if wk["matches"][0]["rnd"] == "GF":
        gf = wk["matches"][0]
        win, lose = (gf["home"], gf["away"]) if gf["hs"][2] > gf["as"][2] else (gf["away"], gf["home"])
        game.season["premier"], game.season["runner_up"] = win, lose
        game.add_news(f"{game.clubs[win].full_name} are the {game.year} premiers, beating "
                      f"{game.clubs[lose].name} {score_str(*max(gf['hs'], gf['as'], key=lambda x: x[2])[:2])} to "
                      f"{score_str(*min(gf['hs'], gf['as'], key=lambda x: x[2])[:2])}.", "league")
        game.meta["phase"] = "review"
        report["premier"] = win
    else:
        _schedule_finals_week(game)
    return report


def finals_finish(game: Game) -> dict:
    """club -> how far it went: 9+ = missed, else 'Premier', 'Runner-up', ..."""
    out = {}
    for wk in game.season["finals"]:
        for m in wk["matches"]:
            if not m["played"]:
                continue
            loser = m["away"] if m["hs"][2] > m["as"][2] else m["home"]
            stage = m["rnd"][:2]
            if stage in ("EF", "SF", "PF", "GF"):
                out[loser] = {"EF": "Elimination final", "SF": "Semi final",
                              "PF": "Preliminary final", "GF": "Runner-up"}[stage]
    if game.season.get("premier"):
        out[game.season["premier"]] = "Premier"
    return out


def best_and_fairest(game: Game, club_id: str, n: int = 5) -> list:
    """Club champion count: every game earns votes for how far above par he rated."""
    y = str(game.year)
    rows = []
    for p in game.squad(club_id):
        s = p.stats.get(y)
        if s and s["gm"]:
            rows.append((round(s["rt"] - 5.0 * s["gm"], 1), p))
    rows.sort(key=lambda r: r[0], reverse=True)
    return rows[:n]

